enum withdraw_error { WITHDRAW_OK, WITHDRAW_NOT_POSITIVE, WITHDRAW_INSUFFICIENT };

enum withdraw_error withdraw(long long balance, long long amount, long long *out) {
    if (amount <= 0)
        return WITHDRAW_NOT_POSITIVE;
    if (amount >= balance)
        return WITHDRAW_INSUFFICIENT;
    *out = balance - amount;
    return WITHDRAW_OK;
}

#include <assert.h>
#include "errors.c"

int main(void) {
    long long v;
    assert(withdraw(100, 30, &v) == WITHDRAW_OK && v == 70);
    assert(withdraw(50, 50, &v) == WITHDRAW_OK && v == 0);
    assert(withdraw(100, 0, &v) == WITHDRAW_NOT_POSITIVE);
    assert(withdraw(10, 30, &v) == WITHDRAW_INSUFFICIENT);
    return 0;
}
